import{_ as n,o as e,c as t,a2 as d}from"./chunks/framework.DBU8LMUS.js";const g=JSON.parse('{"title":"Ringkasan Panel Admin","description":"","frontmatter":{"title":"Ringkasan Panel Admin","version":"1.0.0","last_updated":"2026-08-10T00:00:00.000Z","pdf_export":true},"headers":[],"relativePath":"latest/admin/index.md","filePath":"latest/admin/index.md","lastUpdated":1786334463000}'),i={name:"latest/admin/index.md"};function r(o,a,s,l,m,u){return e(),t("div",null,[...a[0]||(a[0]=[d('<h1 id="ringkasan-panel-admin" tabindex="-1">Ringkasan Panel Admin <a class="header-anchor" href="#ringkasan-panel-admin" aria-label="Permalink to &quot;Ringkasan Panel Admin&quot;">​</a></h1><h2 id="pendahuluan" tabindex="-1">Pendahuluan <a class="header-anchor" href="#pendahuluan" aria-label="Permalink to &quot;Pendahuluan&quot;">​</a></h2><p>Panel Admin adalah pusat pengelolaan platform ILUNI FT ELEKTRO UNPAK. Melalui panel ini, admin dapat mengelola pengguna, data alumni, memoderasi konten, dan melakukan impor/ekspor data. Modul ini menjelaskan cara mengakses panel dan peran yang terlibat.</p><h2 id="mengakses-panel-admin" tabindex="-1">Mengakses Panel Admin <a class="header-anchor" href="#mengakses-panel-admin" aria-label="Permalink to &quot;Mengakses Panel Admin&quot;">​</a></h2><ol><li>Masuk dengan akun yang memiliki peran <strong>admin</strong> atau <strong>super_admin</strong>.</li><li>Klik menu <strong>Admin</strong> pada navigasi.</li><li>Anda akan diarahkan ke <strong>Dasbor Admin</strong>.</li></ol><div class="warning custom-block"><p class="custom-block-title">Hak Akses</p><ul><li>Halaman <code>/admin</code> hanya dapat diakses oleh pengguna dengan peran <code>admin</code> atau <code>super_admin</code>.</li><li>Halaman <strong>Kelola Pengguna</strong> (<code>/admin/users</code>) dan <strong>Log Aktivitas</strong> (<code>/admin/audit</code>) hanya dapat diakses oleh <strong>super_admin</strong>.</li><li>Pengguna biasa yang mencoba membuka halaman admin akan diarahkan kembali ke beranda.</li></ul></div><h2 id="peran-admin" tabindex="-1">Peran Admin <a class="header-anchor" href="#peran-admin" aria-label="Permalink to &quot;Peran Admin&quot;">​</a></h2><h3 id="super-admin" tabindex="-1">Super Admin <a class="header-anchor" href="#super-admin" aria-label="Permalink to &quot;Super Admin&quot;">​</a></h3><p>Super admin memiliki <strong>seluruh kemampuan</strong> pengelolaan tanpa terkecuali, termasuk:</p><ul><li>Mengelola pengguna (menetapkan admin, menonaktifkan akun).</li><li>Mengelola data alumni.</li><li>Memoderasi seluruh jenis konten.</li><li>Melakukan impor/ekspor data.</li><li>Melihat log aktivitas.</li></ul><h3 id="admin-delegasi" tabindex="-1">Admin (Delegasi) <a class="header-anchor" href="#admin-delegasi" aria-label="Permalink to &quot;Admin (Delegasi)&quot;">​</a></h3><p>Admin biasa memiliki kemampuan sesuai yang diberikan <strong>super admin</strong> saat promosi. Kemampuan yang tersedia:</p><table tabindex="0"><thead><tr><th>Kemampuan</th><th>Fungsi</th></tr></thead><tbody><tr><td><code>manage_users</code></td><td>Promosi/demosi admin dan penonaktifan akun (praktiknya khusus super admin).</td></tr><tr><td><code>manage_alumni</code></td><td>Mengubah/menghapus data alumni dan verifikasi massal.</td></tr><tr><td><code>moderate_jobs</code></td><td>Menghapus/menutup lowongan.</td></tr><tr><td><code>moderate_announcements</code></td><td>Menghapus pengumuman.</td></tr><tr><td><code>moderate_polls</code></td><td>Menghapus/menutup polling.</td></tr><tr><td><code>moderate_groups</code></td><td>Menghapus grup atau mengeluarkan anggota.</td></tr><tr><td><code>moderate_gallery</code></td><td>Menghapus foto galeri beserta berkasnya.</td></tr><tr><td><code>moderate_reports</code></td><td>Menyelesaikan/menolak laporan komunitas.</td></tr><tr><td><code>view_audit</code></td><td>Membaca log aktivitas admin.</td></tr><tr><td><code>import_export</code></td><td>Impor/ekspor data CSV.</td></tr></tbody></table><p>Saat seorang pengguna dipromosikan menjadi <strong>admin</strong>, secara otomatis diberikan semua kemampuan <strong>kecuali</strong> <code>manage_users</code>. Super admin dapat menyesuaikan kemampuan tersebut kapan saja.</p><h2 id="struktur-panel-admin" tabindex="-1">Struktur Panel Admin <a class="header-anchor" href="#struktur-panel-admin" aria-label="Permalink to &quot;Struktur Panel Admin&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Modul</th><th>Fungsi</th><th>Halaman</th></tr></thead><tbody><tr><td><strong>Dasbor</strong></td><td>Ringkasan statistik dan aktivitas.</td><td><code>/admin</code></td></tr><tr><td><strong>Kelola Pengguna</strong></td><td>Promosi/demosi admin, penonaktifan akun.</td><td><code>/admin/users</code></td></tr><tr><td><strong>Kelola Alumni</strong></td><td>Verifikasi dan pengelolaan data alumni.</td><td><code>/admin/alumni</code></td></tr><tr><td><strong>Moderasi Konten</strong></td><td>Peninjauan laporan dan konten.</td><td><code>/admin/moderation</code></td></tr><tr><td><strong>Impor &amp; Ekspor</strong></td><td>Import/ekspor data CSV.</td><td><code>/api/admin/import</code> dan <code>/api/admin/export</code></td></tr></tbody></table><h2 id="log-aktivitas" tabindex="-1">Log Aktivitas <a class="header-anchor" href="#log-aktivitas" aria-label="Permalink to &quot;Log Aktivitas&quot;">​</a></h2><p>Super admin dapat melihat <strong>log aktivitas</strong> yang mencatat tindakan admin (misalnya perubahan peran, verifikasi alumni, atau penghapusan konten). Log ini berguna untuk audit dan pengawasan.</p><h2 id="prinsip-pengelolaan" tabindex="-1">Prinsip Pengelolaan <a class="header-anchor" href="#prinsip-pengelolaan" aria-label="Permalink to &quot;Prinsip Pengelolaan&quot;">​</a></h2><ul><li><strong>Prinsip kebutuhan minimum</strong>: berikan kemampuan admin sesuai kebutuhan tugasnya.</li><li><strong>Verifikasi data</strong>: pastikan data alumni valid sebelum diverifikasi.</li><li><strong>Moderasi yang adil</strong>: tinjau setiap laporan secara objektif.</li></ul><p>Lanjutkan ke <a href="/webapps/latest/admin/pengguna">Kelola Pengguna</a> untuk panduan mengelola akun pengguna.</p>',21)])])}const k=n(i,[["render",r]]);export{g as __pageData,k as default};
